source_record.canonical_solution:
{
    static char output[50]; // Buffer to hold the output string.

    if (0 <= x && x < 10) {
        sprintf(output, "%.5lf", cos(x + 3.0));
    } else if (10 <= x && x < 20) {
        sprintf(output, "%.5lf", pow(cos(x + 7.5), 2.0));
    } else if (20 <= x && x < 30) {
        sprintf(output, "%.5lf", pow(cos(x + 4.0), 4.0));
    } else {
        return "Not define";
    }
    return output;
}

