#include <string.h>
unsigned long long count_valid_coin_toss_sequences(int n)
{
    unsigned long long a[41][2];
    a[1][0] = a[1][1] = 1;

    for(int i = 2; i <= n; i++){
        a[i][0] = a[i - 1][1] + a[i - 1][0];
        a[i][1] = a[i - 1][0];
    }

    return a[n][0] + a[n][1];
}

