Given a permutation q of n elements and an integer k, find the number of permutations p of n elements such that f(p) = q, where f(p) is the lexicographically smallest permutation that can be obtained by dividing p into exactly k non-empty contiguous segments and sorting each segment(that is, choose $ k-1 $ breakpoints $ 1\le x_1 < x_2 < \cdots < x_{k-1} < n $, and divide it into $ [1, x_1], (x_1, x_2], \cdots, (x_{k-1}, n] $). The result should be modulo 998244353.
    >>> countPermutations(2, 1, [1, 2])
    2

*/
int countPermutations(int n, int k, int qq[])

source_record.canonical_solution:
{
    const int N = 505, P = 998244353;
    int q[N], m, dp[N][N], jc[N], f[N], ans;
    memset(q, 0, sizeof(q));
    memset(dp, 0, sizeof(dp));
    memset(jc, 0, sizeof(jc));
    memset(f, 0, sizeof(f));
    ans = 0;

    for (int i = 1; i <= n; i++)
        q[i] = qq[i - 1];
    dp[0][0] = f[0] = 1;
    for (int i = jc[0] = 1; i <= n; i++)
        jc[i] = 1LL * jc[i - 1] * i % P;
    for (int i = 1; i <= n; i++)
    {
        f[i] = jc[i];
        for (int j = 1; j < i; j++)
            f[i] = (f[i] + P - 1LL * f[j] * jc[i - j] % P) % P;
    }
    for (int i = 1; i <= n; i++)
    {
        for (int j = 0; j < i; j++)
            for (int k = 1; k <= n; k++)
                dp[i][k] = (dp[i][k] + dp[j][k - 1] * 1LL * f[i - j] % P) % P;
    }
    m = 0;
    for (int i = 1; i <= n; i++)
        if (q[i] > q[i + 1])
        {
            m = i;
            break;
        }
    if (m == n)
    {
        for (int i = k; i <= n; i++)
            ans = (ans + dp[n][i]) % P;
    }
    else
    {
        for (int i = m + 1; i <= n; i++)
        {
            if (i ^ m + 1 && (q[i - 1] > q[i] || q[i] < q[m]))
                break;
            int c = k + i - n - 1;
            if (c >= 0)
                ans = (ans + dp[m][c] * 1LL * jc[i - m - 1] % P) % P;
        }
    }
    return ans;
}

