        pre[i] = u[i] = 0;
    }
    for (int i = 1; i <= n; i++) {
        pre[i] = u[pixels[i-1]];
        u[pixels[i-1]] = i;
    }
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (i != j) f[i][j] = 1000000000;
            else f[i][j] = 0;
        }
    }
    for (int len = 2; len <= n; len++) {
        for (int i = 1; i <= n - len + 1; i++) {
            int j = i + len - 1;
            f[i][j] = f[i][j - 1] + 1;
            for (int l = pre[j]; l >= i; l = pre[l]) {
                f[i][j] = f[i][j] < f[i][l] + f[l + 1][j] ? f[i][j] : f[i][l] + f[l + 1][j];
            }
        }
    }
    return f[1][n];
}

